create table if not exists public.accounting_accounts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, parent_id uuid references public.accounting_accounts(id) on delete set null, code text not null, name text not null, account_type text not null, active boolean not null default true, unique(organization_id,code));
create table if not exists public.cost_centers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, parent_id uuid references public.cost_centers(id) on delete set null, name text not null, active boolean not null default true, unique(organization_id,name));
create table if not exists public.financial_movements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid references public.farms(id) on delete set null, account_id uuid not null references public.accounting_accounts(id), cost_center_id uuid references public.cost_centers(id) on delete set null, description text not null, amount numeric(14,2) not null check(amount >= 0), movement_date date not null default current_date, due_date date, paid_date date, direction text not null check(direction in ('income','expense')), created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.inventory_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, item_type text not null, unit text not null, minimum_stock numeric(12,2) default 0, active boolean not null default true, unique(organization_id,name));
create table if not exists public.inventory_movements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid references public.farms(id) on delete set null, item_id uuid not null references public.inventory_items(id), quantity numeric(12,2) not null check(quantity > 0), movement_type text not null check(movement_type in ('entry','exit','adjustment')), movement_date date not null default current_date, unit_cost numeric(12,2), notes text, created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.machines (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, machine_type text, registration text, active boolean not null default true, notes text, unique(organization_id,name));
create table if not exists public.machine_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, machine_id uuid not null references public.machines(id) on delete cascade, event_type text not null, event_date date not null default current_date, hours numeric(12,2), kilometers numeric(12,2), fuel_liters numeric(12,2), cost numeric(12,2), notes text, created_at timestamptz not null default now());
create table if not exists public.attachments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid references public.farms(id) on delete set null, name text not null, storage_path text not null, mime_type text, created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.alerts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid references public.farms(id) on delete set null, title text not null, message text, severity text not null default 'info' check(severity in ('info','warning','critical')), due_at timestamptz, resolved_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.module_permissions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, role public.app_role not null, module text not null, can_view boolean not null default false, can_create boolean not null default false, can_edit boolean not null default false, can_delete boolean not null default false, unique(organization_id,role,module));
create table if not exists public.weather_observations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid not null references public.farms(id) on delete cascade, observed_at date not null, temperature_c numeric(6,2), rainfall_mm numeric(8,2), notes text, unique(farm_id,observed_at));
create table if not exists public.feed_regimes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, dry_matter_pct numeric(6,2), cost_per_kg numeric(12,2), active boolean not null default true, unique(organization_id,name));
create table if not exists public.feedlot_batches (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid not null references public.farms(id) on delete cascade, name text not null, start_date date not null, end_date date, target_weight_kg numeric(10,2), notes text, active boolean not null default true, unique(farm_id,name));
create table if not exists public.feedlot_batch_animals (batch_id uuid references public.feedlot_batches(id) on delete cascade, animal_id uuid references public.animals(id) on delete cascade, primary key(batch_id,animal_id));

do $$ declare t text; begin foreach t in array array['accounting_accounts','cost_centers','financial_movements','inventory_items','inventory_movements','machines','machine_events','attachments','alerts','module_permissions','weather_observations','feed_regimes','feedlot_batches'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I_members_read on public.%I for select using (public.is_org_member(organization_id))',t,t); execute format('create policy %I_managers_write on public.%I for all using (public.has_org_role(organization_id,array[''owner'',''admin'',''manager'']::public.app_role[])) with check (public.has_org_role(organization_id,array[''owner'',''admin'',''manager'']::public.app_role[]))',t,t); end loop; end $$;
alter table public.feedlot_batch_animals enable row level security;
create policy feedlot_batch_animals_read on public.feedlot_batch_animals for select using (exists(select 1 from public.feedlot_batches b where b.id=batch_id and public.is_org_member(b.organization_id)));
create policy feedlot_batch_animals_write on public.feedlot_batch_animals for all using (exists(select 1 from public.feedlot_batches b where b.id=batch_id and public.has_org_role(b.organization_id,array['owner','admin','manager','operator']::public.app_role[]))) with check (exists(select 1 from public.feedlot_batches b where b.id=batch_id and public.has_org_role(b.organization_id,array['owner','admin','manager','operator']::public.app_role[])));
create index if not exists financial_movements_org_date on public.financial_movements(organization_id,movement_date desc); create index if not exists inventory_movements_item_date on public.inventory_movements(item_id,movement_date desc); create index if not exists alerts_org_due on public.alerts(organization_id,due_at);
